from __future__ import annotations

import os
from pathlib import Path
from typing import Any

from buvis.pybase.zettel.domain.entities.zettel.zettel import Zettel
from buvis.pybase.zettel.domain.interfaces.zettel_repository import ZettelRepository
from buvis.pybase.zettel.domain.services.zettel_factory import ZettelFactory
from buvis.pybase.zettel.domain.value_objects.zettel_data import ZettelData


def _default_cache_path() -> str:
    xdg = os.environ.get("XDG_CACHE_HOME") or os.path.join(os.path.expanduser("~"), ".cache")
    return os.path.join(xdg, "buvis", "zettel_cache.bin")


try:
    from buvis.pybase.zettel._core import load_all, load_filtered, parse_file

    _HAS_RUST = True
except ImportError:
    _HAS_RUST = False


def _rust_dict_to_zettel_data(raw: dict[str, Any]) -> ZettelData:
    """Convert the dict returned by Rust _core into a ZettelData instance."""
    data = ZettelData()
    data.metadata = dict(raw.get("metadata", {}))
    data.reference = dict(raw.get("reference", {}))
    data.sections = [(h, c) for h, c in raw.get("sections", [])]
    data.file_path = raw.get("file_path") or None
    return data


def _warn_parse_errors(errors: list[tuple[str, str]]) -> None:
    if not errors:
        return
    from buvis.pybase.adapters.console.console import console
    from rich.markup import escape

    paths = ", ".join(escape(path) for path, _ in errors)
    console.warning(f"{len(errors)} note(s) could not be parsed and were skipped: {paths}")


class MarkdownZettelRepository(ZettelRepository):
    def __init__(
        self,
        zettelkasten_path: Path | None = None,
        extensions: list[str] | None = None,
    ) -> None:
        self.zettelkasten_path = zettelkasten_path
        self._extensions = extensions or ["md"]

    def save(self, zettel: Zettel) -> None:
        from buvis.pybase.zettel.infrastructure.formatting.markdown_zettel_formatter.markdown_zettel_formatter import (
            MarkdownZettelFormatter,
        )

        zettel.ensure_consistency()
        data = zettel.get_data()
        if not data.file_path:
            raise ValueError("Cannot save zettel without file_path")
        formatted = MarkdownZettelFormatter.format(data)
        Path(data.file_path).write_text(formatted, encoding="utf-8")

    def delete(self, zettel: Zettel) -> None:
        data = zettel.get_data()
        if not data.file_path:
            raise ValueError("Cannot delete zettel without file_path")
        Path(data.file_path).unlink()

    def find_by_id(self, zettel_id: str) -> Zettel:
        if self.zettelkasten_path is None:
            raise ValueError("zettelkasten_path required for find_by_id")
        path = self.zettelkasten_path / f"{zettel_id}.md"
        return self.find_by_location(str(path))

    def find_by_location(self, repository_location: str) -> Zettel:
        if _HAS_RUST:
            raw = parse_file(repository_location)
            zettel_data = _rust_dict_to_zettel_data(raw)
            return ZettelFactory.create(Zettel(zettel_data, from_rust=True))

        # Fallback to pure-Python parser
        from buvis.pybase.zettel.infrastructure.persistence.file_parsers.zettel_file_parser import (
            ZettelFileParser,
        )

        zettel_data = ZettelFileParser.from_file(Path(repository_location))
        zettel_data.file_path = str(repository_location)
        return ZettelFactory.create(Zettel(zettel_data))

    def find_all(
        self,
        directory: str,
        metadata_eq: dict[str, Any] | None = None,
    ) -> list[Zettel]:
        errors: list[tuple[str, str]]
        if _HAS_RUST:
            if metadata_eq:
                cp = _default_cache_path()
                raw_list, errors = load_filtered(directory, self._extensions, metadata_eq, cp)
            else:
                raw_list, errors = load_all(directory, self._extensions)
            _warn_parse_errors(errors)
            return [ZettelFactory.create(Zettel(_rust_dict_to_zettel_data(raw), from_rust=True)) for raw in raw_list]

        from buvis.pybase.zettel.infrastructure.persistence.file_parsers.zettel_file_parser import (
            ZettelFileParser,
        )

        exts = self._extensions
        dir_path = Path(directory).expanduser().resolve()
        zettels: list[Zettel] = []
        errors = []
        for ext in exts:
            for file_path in sorted(dir_path.rglob(f"*.{ext}")):
                try:
                    zettel_data = ZettelFileParser.from_file(file_path)
                except (OSError, ValueError) as exc:
                    errors.append((str(file_path), str(exc)))
                    continue
                if metadata_eq and not all(zettel_data.metadata.get(k) == v for k, v in metadata_eq.items()):
                    continue
                zettel_data.file_path = str(file_path)
                zettels.append(ZettelFactory.create(Zettel(zettel_data)))
        _warn_parse_errors(errors)
        return zettels

from __future__ import annotations

from unittest.mock import MagicMock, patch

import pytest
from buvis.pybase.zettel.domain.entities.zettel.zettel import Zettel
from buvis.pybase.zettel.domain.value_objects.zettel_data import ZettelData
from buvis.pybase.zettel.infrastructure.persistence.markdown_zettel_repository.markdown_zettel_repository import (
    MarkdownZettelRepository,
)


@pytest.fixture
def repository() -> MarkdownZettelRepository:
    return MarkdownZettelRepository()


@pytest.fixture
def repository_with_path(tmp_path) -> MarkdownZettelRepository:
    return MarkdownZettelRepository(zettelkasten_path=tmp_path)


class TestSave:
    @patch(
        "buvis.pybase.zettel.infrastructure.formatting.markdown_zettel_formatter.markdown_zettel_formatter.MarkdownZettelFormatter.format"
    )
    def test_save_writes_formatted_content(self, mock_format, repository, tmp_path) -> None:
        file_path = tmp_path / "zettel.md"
        zettel_data = ZettelData(file_path=str(file_path))
        zettel = MagicMock(spec=Zettel)
        zettel.get_data.return_value = zettel_data
        mock_format.return_value = "formatted content"

        repository.save(zettel)

        assert file_path.read_text(encoding="utf-8") == "formatted content"

    def test_save_raises_without_file_path(self, repository) -> None:
        zettel_data = ZettelData()
        zettel = MagicMock(spec=Zettel)
        zettel.get_data.return_value = zettel_data

        with pytest.raises(ValueError):
            repository.save(zettel)


class TestDelete:
    def test_delete_removes_file(self, repository, tmp_path) -> None:
        file_path = tmp_path / "zettel.md"
        file_path.write_text("content")
        zettel_data = ZettelData(file_path=str(file_path))
        zettel = MagicMock(spec=Zettel)
        zettel.get_data.return_value = zettel_data

        repository.delete(zettel)

        assert not file_path.exists()

    def test_delete_raises_without_file_path(self, repository) -> None:
        zettel_data = ZettelData()
        zettel = MagicMock(spec=Zettel)
        zettel.get_data.return_value = zettel_data

        with pytest.raises(ValueError):
            repository.delete(zettel)


class TestFindById:
    def test_find_by_id_delegates_to_find_by_location(
        self,
        repository_with_path,
        tmp_path,
    ) -> None:
        expected = MagicMock(spec=Zettel)
        repository_with_path.find_by_location = MagicMock(return_value=expected)

        result = repository_with_path.find_by_id("20250101120000")

        assert result == expected
        repository_with_path.find_by_location.assert_called_once_with(str(tmp_path / "20250101120000.md"))

    def test_find_by_id_raises_without_zettelkasten_path(self, repository) -> None:
        with pytest.raises(ValueError):
            repository.find_by_id("20250101120000")
